<!-- about-hero -->
<section class="about-hero section-bg">
    <div class="container">
        <div class="about-hero__content">
            <nav class="breadcrumbs fade-in" aria-label="Breadcrumb" role="navigation" itemscope itemtype="https://schema.org/BreadcrumbList">
                <ol class="breadcrumbs__list">
                    <li class="breadcrumbs__item" itemprop="itemListElement" itemscope itemtype="https://schema.org/ListItem">
                        <a class="breadcrumbs__link" href="./" itemprop="item">
                            <span itemprop="name">Главная</span>
                        </a>
                        <meta itemprop="position" content="1" />
                    </li>
                    <li class="breadcrumbs__item breadcrumbs__item--current" itemprop="itemListElement" itemscope itemtype="https://schema.org/ListItem" aria-current="page">
                        <span class="breadcrumbs__link" itemprop="item">
                            <span itemprop="name">О VILTI</span>
                        </span>
                        <meta itemprop="position" content="2" />
                    </li>
                </ol>
            </nav>
            <div class="head-content fade-in-up">
                <h1 class="title title--h2">Премиальный <br>девелопер <br>загородного <br>домостроения</h1>
                <div class="subtitle">We build legacies, quietly</div>
            </div>
        </div>
    </div>
    <div class="section-bg__cover fade-in">
        <picture>
            <!-- Mobile -->
            <source srcset="img/default.png" data-srcset="img/about-hero/bg-xs.webp 1x, img/about-hero/bg-xs@2x.webp 2x" media="(max-width:479px)" type="image/webp">
            <source srcset="img/default.png" data-srcset="img/about-hero/bg-xs.jpg 1x, img/about-hero/bg-xs@2x.jpg 2x" media="(max-width:479px)" type="image/jpeg">
            <!-- Desktop -->
            <source srcset="img/default.png" data-srcset="img/about-hero/bg.webp 1x, img/about-hero/bg@2x.webp 2x" type="image/webp">
            <source srcset="img/default.png" data-srcset="img/about-hero/bg.jpg 1x, img/about-hero/bg@2x.jpg 2x" type="image/jpeg">
            <img class="lazyload" src="img/default.png" data-srcset="img/about-hero/bg.jpg 1x, img/about-hero/bg@2x.jpg 2x" alt="img">
        </picture>
    </div>
</section>